        local ok, err = pcall(function()
            local data = Http:JSONEncode(model:export())
            if #data > 12 * 1024 * 1024 then error("Saved scripts exceed the 12 MiB storage limit", 0) end
            writeFile(fileName, data)
        end)
        if ok then dirty = false; storageFailed = false
        else
            if not storageFailed then addLog("WARN", "Workspace save failed: " .. tostring(err)) end
            storageFailed = true
            status("Workspace save failed; scripts remain in this session", "error")
        end
    end
    local function scheduleSave()
        dirty = true
        saveRevision += 1
        local revision = saveRevision
        task.delay(.8, function()
            if alive and revision == saveRevision then persist() end
        end)
    end
    local function updateEditorGeometry()
        if not alive then return end
        local lineCount, longest = 0, 0
        for single in string.gmatch(editor.Text .. "\n", "(.-)\n") do
            lineCount += 1
            longest = math.max(longest, #single)
        end
        lineCount = math.max(1,lineCount)
        local height = math.max(editorScroll.AbsoluteSize.Y / math.max(uiScale.Scale,.01), lineCount*26+40)
        local width = math.max(editorScroll.AbsoluteSize.X / math.max(uiScale.Scale,.01), math.min(longest, 40000)*13.3+116)
        editor.Size = UDim2.fromOffset(width-92,height)
        numbers.Size = UDim2.fromOffset(52,height)
        local lineLabels = {}
        -- Huge scripts still execute, but do not allocate hundreds of thousands of labels.
        for index = 1, math.min(lineCount,10000) do table.insert(lineLabels,tostring(index)) end
        numbers.Text = table.concat(lineLabels,"\n")
        editorScroll.CanvasSize = UDim2.fromOffset(width,height)
    end
    local function loadActiveEditor()
        loadingEditor = true
        editor.Text = model:active().source
        loadingEditor = false
        editorScroll.CanvasPosition = Vector2.new(0,0)
        updateEditorGeometry()
    end
    local tabConnections = {}
    renderTabs = function()
        disconnectGroup(tabConnections)
        for _, child in tabScroll:GetChildren() do child:Destroy() end
        for index, tab in model.tabs do
            local active = tab.id == model.activeId
            local tabButton = button(tabScroll, "Tab_"..tab.id, "", UDim2.fromOffset((index-1)*222,0),
                UDim2.fromOffset(212,62), nil, function()
                    model:select(tab.id); loadActiveEditor(); renderTabs(); scheduleSave()
                end, active, tabConnections)
            icon(tabButton,"file",UDim2.fromOffset(14,18),26)
            label(tabButton,tab.title,UDim2.fromOffset(50,0),UDim2.new(1,-92,1,0),20)
            local closeTab = button(tabButton,"CloseTab_"..tab.id,"",UDim2.new(1,-43,0,10),UDim2.fromOffset(38,42),nil,function()
                model:closeTab(tab.id); loadActiveEditor(); renderTabs(); scheduleSave()
            end,false,tabConnections)
            closeTab.BackgroundTransparency = 1
            icon(closeTab,"close",UDim2.fromOffset(7,9),24)
        end
        tabScroll.CanvasSize = UDim2.fromOffset(#model.tabs*222,0)
    end
    button(editorPage,"NewTabButton","",UDim2.new(1,-82,0,18),UDim2.fromOffset(64,62),"add",function()
        local tab, err = model:addTab("New tab", "")
        if not tab then status(err,"error"); return end
        loadActiveEditor(); renderTabs(); scheduleSave()
        tabScroll.CanvasPosition = Vector2.new(math.max(0,#model.tabs*222-1200),0)
    end)
    bind(editor:GetPropertyChangedSignal("Text"),function()
        if loadingEditor or not alive then return end
        local ok, err = model:setSource(editor.Text)
        if not ok then loadActiveEditor(); status(err,"error"); return end
        updateEditorGeometry(); scheduleSave()
    end)
    bind(editorScroll:GetPropertyChangedSignal("AbsoluteSize"),updateEditorGeometry)

    local function execute(source, title)
        running += 1
        status("Running " .. title .. "...")
        addLog("RUN",title)
        task.spawn(function()
            local result = Core.execute(compiler,source,title)
            running -= 1
            if not alive then return end
            if result.ok then
                status(if running > 0 then tostring(running).." script(s) still running" else "Finished: "..title,"success")
                addLog("OK",title.." finished")
            else
                addLog(string.upper(result.phase),result.message)
                status(result.phase..": "..result.message,"error")
                consoleOpen = true; console.Visible = true
            end
        end)
    end

    -- Dialogs use normal TextBoxes so clipboard actions work with Ctrl+V even
    -- when an executor offers setclipboard but no getclipboard.
    local modal = frame(root,"ModalOverlay",UDim2.fromOffset(0,0),UDim2.fromScale(1,1),C.black)
    modal.BackgroundTransparency = .32; modal.ZIndex = 20; modal.Visible = false
    sinkInput(modal)
    local dialog = frame(modal,"Dialog",UDim2.fromScale(.5,.5),UDim2.fromOffset(720,430),C.panel,28)
    dialog.AnchorPoint = Vector2.new(.5,.5); stroke(dialog)
    local dialogTitle = label(dialog,"Paste script",UDim2.fromOffset(28,22),UDim2.new(1,-110,0,42),28)
    local dialogHint = label(dialog,"Click below and press Ctrl+V.",UDim2.fromOffset(28,68),UDim2.new(1,-56,0,34),18,C.muted)
    local dialogBox = new("TextBox", { Name = "DialogInput", Position = UDim2.fromOffset(28,118),
        Size = UDim2.new(1,-56,1,-222), BackgroundColor3 = C.soft, BorderSizePixel = 0,
        Text = "", PlaceholderText = "Ctrl+V", PlaceholderColor3 = C.muted, TextColor3 = C.white,
        Font = Enum.Font.Code, TextSize = 20, ClearTextOnFocus = false, MultiLine = true,
        TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top,
        TextWrapped = true, ClipsDescendants = true },dialog)
    corner(dialogBox,12)
    new("UIPadding",{ PaddingLeft = UDim.new(0,14),PaddingRight = UDim.new(0,14),
        PaddingTop = UDim.new(0,12),PaddingBottom = UDim.new(0,12) },dialogBox)
    local dialogAction, dialogValidation
    local confirm = button(dialog,"DialogConfirm","Insert",UDim2.new(1,-230,1,-78),UDim2.fromOffset(202,54),"paste",function()
        if dialogValidation and not dialogValidation(dialogBox.Text) then return end
        local action = dialogAction
        modal.Visible = false; dialogBox:ReleaseFocus()
        if action then action(dialogBox.Text) end
    end,true)
    local confirmText = confirm:FindFirstChild("Label")
    local function closeDialog()
        modal.Visible = false; dialogBox:ReleaseFocus()
    end
    button(dialog,"DialogClose","",UDim2.new(1,-72,0,20),UDim2.fromOffset(48,48),"close",closeDialog)
    button(dialog,"DialogCancel","Cancel",UDim2.fromOffset(28,352),UDim2.fromOffset(160,54),nil,closeDialog)
    local function showDialog(title,hint,initial,actionText,action,validation,singleLine)
        dialogTitle.Text, dialogHint.Text = title,hint
        dialogBox.Text = initial or ""
        dialogBox.MultiLine = not singleLine
        dialogBox.TextWrapped = not singleLine
        confirmText.Text = actionText
        dialogAction, dialogValidation = action,validation
        modal.Visible = true
        task.defer(function() if alive and modal.Visible then dialogBox:CaptureFocus() end end)
    end
    local function validateSource(text)
        if #text > Core.MAX_SOURCE then dialogHint.Text = "Script exceeds the 1 MiB limit"; return false end
        if not string.find(text,"%S") then dialogHint.Text = "Paste a script first"; return false end
        return true
    end
    local function paste(shouldExecute)
        if getClipboard then
            local ok, text = pcall(getClipboard)
            if ok and type(text) == "string" and #text <= Core.MAX_SOURCE and string.find(text,"%S") then
                if shouldExecute then execute(text,"Clipboard")
                else model:setSource(text); loadActiveEditor(); scheduleSave(); status("Pasted into editor","success") end
                return
            end
        end
        showDialog(if shouldExecute then "Execute clipboard" else "Paste script",
            "Press Ctrl+V below, then "..(if shouldExecute then "Execute." else "Insert."), "",
            if shouldExecute then "Execute" else "Insert",function(text)
                if shouldExecute then execute(text,"Clipboard")
                else model:setSource(text); loadActiveEditor(); scheduleSave(); status("Pasted into editor","success") end
            end,validateSource,false)
    end

    button(editorPage,"ExecuteButton","Execute",UDim2.new(0,18,1,-78),UDim2.fromOffset(172,60),"execute",function()
        local tab = model:active(); execute(tab.source,tab.title)
    end)
    button(editorPage,"ClearButton","Clear",UDim2.new(0,200,1,-78),UDim2.fromOffset(150,60),"clear",function()
        model:setSource(""); loadActiveEditor(); scheduleSave(); status("Editor cleared")
    end)
    button(editorPage,"PasteButton","Paste",UDim2.new(0,360,1,-78),UDim2.fromOffset(150,60),"paste",function() paste(false) end)
    button(editorPage,"SaveButton","Save",UDim2.new(0,520,1,-78),UDim2.fromOffset(146,60),"save",function()
        if not string.find(model:active().source,"%S") then status("The editor is empty","error"); return end
        showDialog("Save script","A matching name updates the existing saved script.",model:active().title,"Save",function(title)
            local item, action = model:saveScript(title,model:active().source)
            if not item then status(action,"error"); return end
            model:renameActive(item.title); renderTabs(); renderLibrary(); scheduleSave()
            status(item.title.." "..action.." to library"..(if writeFile then "" else " for this session"),"success")
        end,function(title)
            if not string.find(title,"%S") or #title > 96 then dialogHint.Text = "Use a name between 1 and 96 bytes"; return false end
            return true
        end,true)
    end)
    button(editorPage,"ExecuteClipboardButton","Execute clipboard",UDim2.new(1,-294,1,-78),UDim2.fromOffset(276,60),"paste",function() paste(true) end)

    local library = pages.library
    label(library,"Script library",UDim2.fromOffset(32,26),UDim2.new(1,-64,0,52),32)
    label(library,"Your saved scripts. Open to edit, or run a script you saved.",UDim2.fromOffset(32,80),UDim2.new(1,-64,0,32),20,C.muted)
    local search = new("TextBox",{ Name = "LibrarySearch",Position = UDim2.fromOffset(32,132),Size = UDim2.new(1,-64,0,54),
        BackgroundColor3 = C.soft,BorderSizePixel = 0,Text = "",PlaceholderText = "Search saved scripts...",
        PlaceholderColor3 = C.muted,TextColor3 = C.white,TextSize = 21,Font = Enum.Font.Gotham,
        ClearTextOnFocus = false,TextXAlignment = Enum.TextXAlignment.Left },library)
    corner(search,16); new("UIPadding",{PaddingLeft = UDim.new(0,18)},search)
    local libraryScroll = new("ScrollingFrame",{Name = "LibraryList",Position = UDim2.fromOffset(32,206),
        Size = UDim2.new(1,-64,1,-340),BackgroundTransparency = 1,BorderSizePixel = 0,
        CanvasSize = UDim2.fromOffset(0,0),ScrollBarThickness = 5,ScrollBarImageColor3 = C.edge},library)
    local function openSaved(item)
        local tab, err = model:addTab(item.title,item.source)
        if not tab then status(err,"error"); return end
        loadActiveEditor(); renderTabs(); scheduleSave(); navigate("editor")
        status("Opened "..item.title,"success")
    end
    renderLibrary = function()
        disconnectGroup(ephemeralConnections)
        for _, child in libraryScroll:GetChildren() do child:Destroy() end
        local query = string.lower(search.Text)
        local count = 0
        for _, item in model.library do
            if string.find(string.lower(item.title),query,1,true) then
                local row = frame(libraryScroll,"Saved_"..item.id,UDim2.fromOffset(0,count*110),UDim2.new(1,-12,0,94),C.soft,18)
                icon(row,"file",UDim2.fromOffset(20,28),34)
                label(row,item.title,UDim2.fromOffset(72,12),UDim2.new(1,-570,0,38),24)
                label(row,string.format("%.1f KB of Luau",#item.source/1024),UDim2.fromOffset(72,49),UDim2.new(1,-570,0,28),17,C.muted)
                button(row,"LibraryOpen_"..item.id,"Open",UDim2.new(1,-472,0,20),UDim2.fromOffset(144,54),"file",function() openSaved(item) end,false,ephemeralConnections)
                button(row,"LibraryRun_"..item.id,"Run",UDim2.new(1,-318,0,20),UDim2.fromOffset(134,54),"execute",function() execute(item.source,item.title) end,true,ephemeralConnections)
                button(row,"LibraryDelete_"..item.id,"Delete",UDim2.new(1,-174,0,20),UDim2.fromOffset(156,54),"clear",function()
                    model:deleteScript(item.id); renderLibrary(); scheduleSave(); status("Deleted "..item.title)
                end,false,ephemeralConnections)
                count += 1
            end
        end
        if count == 0 then label(libraryScroll,if #model.library == 0 then "Nothing saved yet. Use Save in the editor." else "No matching scripts.",UDim2.fromOffset(12,20),UDim2.new(1,-24,0,44),22,C.muted) end
        libraryScroll.CanvasSize = UDim2.fromOffset(0,count*110)
    end
    bind(search:GetPropertyChangedSignal("Text"),renderLibrary)

    local function card(parent,name,title,subtitle,x,y,w,h,glyph)
        local object = frame(parent,name,UDim2.fromOffset(x,y),UDim2.fromOffset(w,h),C.soft,24)
        stroke(object)
        icon(object,glyph,UDim2.fromOffset(26,26),36)
        label(object,title,UDim2.fromOffset(26,82),UDim2.new(1,-52,0,40),27)
        local detail = label(object,subtitle,UDim2.fromOffset(26,132),UDim2.new(1,-52,0,72),20,C.muted)
        detail.TextWrapped = true; detail.TextYAlignment = Enum.TextYAlignment.Top
        return object
    end
    local home = pages.home
    label(home,"Welcome, "..(player.DisplayName or player.Name),UDim2.fromOffset(36,28),UDim2.new(1,-72,0,62),38)
    label(home,"Delta PC  /  your scripts, your session",UDim2.fromOffset(36,96),UDim2.new(1,-72,0,36),21,C.muted)
    local editorCard = card(home,"EditorCard","Script editor","Independent tabs, clipboard actions and execution through your current executor.",36,176,824,300,"terminal")
    button(editorCard,"HomeOpenEditor","Open editor",UDim2.fromOffset(26,228),UDim2.fromOffset(240,52),"terminal",function() navigate("editor") end,true)
    local libraryCard = card(home,"LibraryCard","Your library","Save scripts locally and open them again whenever you need them.",884,176,868,300,"library")
    button(libraryCard,"HomeOpenLibrary","Open library",UDim2.fromOffset(26,228),UDim2.fromOffset(240,52),"library",function() navigate("library") end)
    local demoCard = card(home,"DemoCard","Quick test","Run a small print statement to check the executor and console.",36,502,824,250,"execute")
    button(demoCard,"RunDemo","Run test",UDim2.fromOffset(26,178),UDim2.fromOffset(240,52),"execute",function()
        execute('print("Hello from Delta PC")',"Quick test")
        consoleOpen = true; console.Visible = true
    end)
    card(home,"SessionCard","Ready when you are","Right Ctrl hides or shows the menu. The blue Delta button brings it back too.",884,502,868,250,"delta")

    local workspacePage = pages.workspace
    label(workspacePage,"Workspace",UDim2.fromOffset(36,28),UDim2.new(1,-72,0,62),36)
    label(workspacePage,"Your current executor provides execution, clipboard and local file capabilities.",UDim2.fromOffset(36,94),UDim2.new(1,-72,0,40),21,C.muted)
    local capabilityRows = {
        { "Script execution", if compiler then "loadstring available" else "Unavailable in this environment", compiler ~= nil },
        { "Clipboard paste", if getClipboard then "Direct clipboard read available" else "Use Paste, then Ctrl+V in the dialog", true },
        { "Clipboard copy", if setClipboard then "Copy available" else "Select editor text and press Ctrl+C", true },
        { "Saved workspace", if readFile and writeFile then fileName elseif writeFile then "Write only; restore unavailable" else "Session memory only", writeFile ~= nil },
        { "Avatar", player.Name .. "  /  User ID "..tostring(player.UserId), true },
    }
    for index, row in capabilityRows do
        local object = frame(workspacePage,"Capability_"..index,UDim2.fromOffset(36,166+(index-1)*100),UDim2.new(1,-72,0,82),C.soft,18)
        label(object,row[1],UDim2.fromOffset(24,0),UDim2.fromOffset(360,82),23)
        label(object,row[2],UDim2.fromOffset(410,0),UDim2.new(1,-440,1,0),21,if row[3] then C.green else C.yellow)
    end
    button(workspacePage,"CopyEditorButton","Copy editor",UDim2.fromOffset(36,704),UDim2.fromOffset(250,58),"copy",function()
        if setClipboard then
            local ok, err = pcall(setClipboard,model:active().source)
            if ok then status("Editor copied","success") else status("Copy failed: "..tostring(err),"error") end
        else
            navigate("editor"); editor:CaptureFocus(); editor.SelectionStart = 1; editor.CursorPosition = #editor.Text+1
            status("Press Ctrl+C to copy the selected script")
        end
    end)
    button(workspacePage,"SaveWorkspaceButton","Save workspace",UDim2.fromOffset(304,704),UDim2.fromOffset(278,58),"save",function()
        if not writeFile then status("File saving is unavailable; scripts stay in this session","error"); return end
        dirty = true; persist()
        if not dirty then status("Workspace saved","success") end
    end)

    local settings = pages.settings
    label(settings,"Settings",UDim2.fromOffset(36,28),UDim2.new(1,-72,0,62),36)
    label(settings,"Adjust the menu to fit your screen.",UDim2.fromOffset(36,94),UDim2.new(1,-72,0,40),21,C.muted)
    local scaleCard = card(settings,"ScaleCard","Menu size","Automatic screen fitting is always applied. Adjust the size below.",36,168,824,284,"settings")
    local scaleText = label(scaleCard,"100%",UDim2.fromOffset(304,214),UDim2.fromOffset(130,50),24)
    local transparencyCard = card(settings,"TransparencyCard","Panel transparency","Keep the game visible behind the menu.",884,168,868,284,"settings")
    local transparencyText = label(transparencyCard,"12%",UDim2.fromOffset(304,214),UDim2.fromOffset(130,50),24)
    local function applyAppearance()
        main.BackgroundTransparency = model.settings.transparency
        side.BackgroundTransparency = model.settings.transparency
        nav.BackgroundTransparency = model.settings.transparency
        scaleText.Text = tostring(math.floor(model.settings.scale*100+.5)).."%"
        transparencyText.Text = tostring(math.floor(model.settings.transparency*100+.5)).."%"
        if resize then resize() end
        scheduleSave()
    end
    button(scaleCard,"ScaleDown","Smaller",UDim2.fromOffset(26,214),UDim2.fromOffset(210,50),nil,function()
        model.settings.scale = math.clamp(model.settings.scale-.05,.75,1); applyAppearance()
    end)
    button(scaleCard,"ScaleUp","Larger",UDim2.fromOffset(500,214),UDim2.fromOffset(210,50),nil,function()
        model.settings.scale = math.clamp(model.settings.scale+.05,.75,1); applyAppearance()
    end)
    button(transparencyCard,"TransparencyDown","Less",UDim2.fromOffset(26,214),UDim2.fromOffset(210,50),nil,function()
        model.settings.transparency = math.clamp(model.settings.transparency-.05,0,.4); applyAppearance()
    end)
    button(transparencyCard,"TransparencyUp","More",UDim2.fromOffset(500,214),UDim2.fromOffset(210,50),nil,function()
        model.settings.transparency = math.clamp(model.settings.transparency+.05,0,.4); applyAppearance()
    end)
    card(settings,"AboutCard","Delta PC","A familiar menu for your scripts. Open the editor, save your favorites and follow their output in the console.",36,482,1716,216,"delta")
    label(settings,"Shortcut: Right Ctrl  |  Menu has no activation or key prompt",UDim2.fromOffset(36,728),UDim2.new(1,-72,0,40),20,C.muted)

    local navButtons = {}
    navigate = function(name)
        if not pages[name] then return end
        currentPage = name
        for pageName, object in pages do object.Visible = pageName == name end
        for pageName, object in navButtons do
            object.BackgroundColor3 = if pageName == name then C.blue else C.panel
            object.BackgroundTransparency = if pageName == name then 0 else 1
        end
        if name == "library" then renderLibrary() end
    end
    for index, item in { {"home","home"},{"editor","terminal"},{"library","library"},{"workspace","cloud"},{"settings","settings"} } do
        local object = button(nav,"Nav_"..item[1],"",UDim2.fromOffset(9+(index-1)*80,9),UDim2.fromOffset(74,76),nil,function() navigate(item[1]) end)
        corner(object,38); icon(object,item[2],UDim2.fromOffset(20,21),34)
        navButtons[item[1]] = object
    end

    resize = function()
        if not alive then return end
        local camera = Workspace.CurrentCamera
        local viewport = if camera then camera.ViewportSize else Vector2.new(1920,1080)
        -- Cap zoom-in to the screen fit so controls always remain reachable.
        uiScale.Scale = math.max(.1,math.min(viewport.X/1920,viewport.Y/1080)*math.min(model.settings.scale,1))
        updateEditorGeometry()
    end
    local cameraConnection
    local function watchCamera()
        if cameraConnection then cameraConnection:Disconnect(); cameraConnection = nil end
        local camera = Workspace.CurrentCamera
        if camera then cameraConnection = camera:GetPropertyChangedSignal("ViewportSize"):Connect(resize) end
        resize()
    end
    bind(Workspace:GetPropertyChangedSignal("CurrentCamera"),watchCamera)
    bind(Input.InputBegan,function(input,processed)
        if input.KeyCode == Enum.KeyCode.RightControl then
            setVisible(not root.Visible)
        elseif not processed and input.KeyCode == Enum.KeyCode.Escape and modal.Visible then
            closeDialog()
        end
    end)
    bind(Logs.MessageOut,function(message,messageType)
        local kind = if messageType == Enum.MessageType.MessageError then "ERROR"
            elseif messageType == Enum.MessageType.MessageWarning then "WARN" else "LOG"
        addLog(kind,message)
    end)
    local elapsed, frames, consoleElapsed = 0,0,0
    bind(Run.Heartbeat,function(delta)
        if not alive then return end
        elapsed += delta; frames += 1; consoleElapsed += delta
        if consoleDirty and consoleOpen and consoleElapsed >= .15 then renderConsole(); consoleElapsed = 0 end
        if elapsed >= 1 then
            fpsLabel.Text = tostring(math.floor(frames/elapsed+.5)).." FPS"
            clockLabel.Text = os.date("%I:%M %p")
            local ok, ping = pcall(function() return Stats.Network.ServerStatsItem["Data Ping"]:GetValue() end)
            pingLabel.Text = if ok and type(ping) == "number" then tostring(math.floor(ping+.5)).." ms" else "-- ms"
            elapsed, frames = 0,0
        end
    end)

    local controller = { Gui = gui, Model = model }
    controller.Toggle = function() if alive then setVisible(not root.Visible) end end
    controller.Destroy = function()
        if not alive then return end
        persist()
        alive = false; saveRevision += 1
        disconnectGroup(connections); disconnectGroup(tabConnections); disconnectGroup(ephemeralConnections)
        if cameraConnection then cameraConnection:Disconnect(); cameraConnection = nil end
        if environment[singletonKey] == controller then environment[singletonKey] = nil end
        gui:Destroy()
    end
    environment[singletonKey] = controller
    bind(gui.Destroying,function()
        if alive then controller.Destroy() end
    end)
    renderTabs(); renderLibrary(); navigate("editor"); watchCamera()
    main.BackgroundTransparency = model.settings.transparency
    side.BackgroundTransparency = model.settings.transparency
    nav.BackgroundTransparency = model.settings.transparency
    scaleText.Text = tostring(math.floor(model.settings.scale*100+.5)).."%"
    transparencyText.Text = tostring(math.floor(model.settings.transparency*100+.5)).."%"
    addLog("READY","Delta PC opened. Execution backend: your current executor.")
    if not compiler then status("loadstring unavailable; run this menu through Xeno","error")
    else status("Ready  /  Right Ctrl to hide") end
    if diskWarning then addLog("WARN",diskWarning) end
    return controller
end

end)()
return mount(Core)
